function XG(pre,cat,when,w,list,opt){list.forEach((e,i)=>{const [t,text,chs,c2,o2]=e;X(pre+'_'+(i+1),cat,t,c2?and(when,c2):when,w,text,chs,Object.assign({cd:60},opt||{},o2||{}))})}
const marC=()=>!!S.spouse;
const kidsC=()=>S.kids&&S.kids.length>0;
const sibC=()=>S.sibs&&S.sibs.length>0;
const parC=()=>parents().length>0;
const yrC=(a,b)=>()=>S.y>=a&&S.y<=(b==null?9999:b);
const hiF=n=>()=>S.snsOpen&&totalF()>=n;
const townC=()=>!!(S.town&&S.town.tiles);
const offC=()=>!!S.office;
const retC=()=>S.st==='retired';
const crC=()=>S.st==='creator';

